"movementPatternId":"7980cd3c-42eb-578a-959f-0f901fe6d9d1","exerciseType":"compound","primaryMuscleId":"23a9cdfd-0152-5be9-ae83-00a1adf0adee","sets":3,"repsMin":8,"repsMax":12,"failure":false,"alternatives":[],"equipmentIds":["5ff1abee-ece7-563c-b7cc-3ad160c3fa2d","ac4abf74-8428-5e8f-a4bf-fe40a9eb1fbe"],"restSeconds":90,"effortScale":"rir","effortValue":3,"progression":"double_progression"},{"exercise":"neutral_grip_cable_lat_pulldown","exerciseId":"fc35de89-1514-5956-aea9-0a06a20a9567","movementPatternId":"5a8208f7-2cd2-5c63-86e6-21b7edf8054e","exerciseType":"compound","primaryMuscleId":"95891341-c8cc-5a87-87b9-c90e1ea47cca","sets":3,"repsMin":8,"repsMax":12,"failure":false,"alternatives":[],"equipmentIds":["03355fa7-9125-51a3-b3e3-d02e931ab1fc"],"restSeconds":90,"effortScale":"rir","effortValue":3,"progression":"double_progression"},{"exercise":"chest_supported_dumbbell_reverse_fly","exerciseId":"157e0c08-824f-5dd7-9036-5e3666f1e60b","movementPatternId":"25c70972-0c15-598d-96c9-9f7e96dd95e3","exerciseType":"isolation","primaryMuscleId":"b0620f84-d8ba-516b-a6cc-4bdf5d87c284","sets":3,"repsMin":8,"repsMax":12,"failure":false,"alternatives":[],"equipmentIds":["5ff1abee-ece7-563c-b7cc-3ad160c3fa2d","ac4abf74-8428-5e8f-a4bf-fe40a9eb1fbe"],"restSeconds":90,"effortScale":"rir","effortValue":3,"progression":"double_progression"},{"exercise":"dumbbell_lateral_raise","exerciseId":"9cf2986d-213d-56bb-bdf9-daacc664ce2d","movementPatternId":"8dda920b-b977-5e12-8db5-3846ec087187","exerciseType":"isolation","primaryMuscleId":"ebf23fc3-0efa-58db-8f81-524ea1b8f919","sets":3,"repsMin":8,"repsMax":12,"failure":false,"alternatives":[],"equipmentIds":["5ff1abee-ece7-563c-b7cc-3ad160c3fa2d"],"restSeconds":90,"effortScale":"rir","effortValue":3,"progression":"double_progression"},{"exercise":"dumbbell_hammer_curl","exerciseId":"65f30f78-a57b-57d5-b643-c23ee2beed42","movementPatternId":"a60b2134-cf9c-5766-95e4-4592856168bd","exerciseType":"isolation","primaryMuscleId":"f77b2bde-68f0-5811